import { beforeEach, describe, expect, it, vi } from 'vitest'
import { flushPromises, mount, type VueWrapper } from '@vue/test-utils'
import { createMemoryHistory, createRouter, type Router } from 'vue-router'

vi.mock('@/api/content', () => ({
  getMenuTree: vi.fn(),
  getAccessRules: vi.fn(),
}))

import { getAccessRules, getMenuTree } from '@/api/content'
import ContentAccessView from './ContentAccessView.vue'

const USER_A = '11111111-1111-1111-1111-111111111111'
const USER_B = '22222222-2222-2222-2222-222222222222'

function createTestRouter(): Router {
  return createRouter({
    history: createMemoryHistory(),
    routes: [
      { path: '/content', name: 'content', component: ContentAccessView },
      { path: '/directory', name: 'directory', component: { template: '<div />' } },
    ],
  })
}

async function mountAt(location: string) {
  const router = createTestRouter()
  await router.push(location)
  await router.isReady()
  const wrapper = mount(ContentAccessView, { global: { plugins: [router] } })
  await flushPromises()
  return { router, wrapper }
}

beforeEach(() => {
  vi.mocked(getMenuTree).mockReset().mockResolvedValue([])
  vi.mocked(getAccessRules).mockReset().mockResolvedValue([])
})

describe('ContentAccessView 딥링크', () => {
  it('진입한 query의 사용자로 접근 정책을 조회한다', async () => {
    await mountAt(`/content?tab=access&userId=${USER_A}`)

    expect(getAccessRules).toHaveBeenCalledTimes(1)
    expect(getAccessRules).toHaveBeenLastCalledWith(expect.objectContaining({ userId: USER_A }))
    expect(getMenuTree).not.toHaveBeenCalled()
  })

  // 사용자·부서 화면에서 다른 사용자의 접근 정책을 누르면 경로는 그대로고 query만 바뀐다.
  it('같은 경로의 query가 바뀌면 새 사용자로 다시 조회한다', async () => {
    const { router } = await mountAt(`/content?tab=access&userId=${USER_A}`)

    await router.push(`/content?tab=access&userId=${USER_B}`)
    await flushPromises()

    expect(getAccessRules).toHaveBeenCalledTimes(2)
    expect(getAccessRules).toHaveBeenLastCalledWith(expect.objectContaining({ userId: USER_B }))
  })

  it('사용자 딥링크에서 부서 딥링크로 바뀌면 이전 사용자 조건을 지운다', async () => {
    const { router } = await mountAt(`/content?tab=access&userId=${USER_A}`)

    await router.push('/content?tab=access&deptId=D100')
    await flushPromises()

    expect(getAccessRules).toHaveBeenLastCalledWith(expect.objectContaining({ deptId: 'D100', userId: undefined }))
  })

  it('query가 비면 메뉴 트리로 돌아간다', async () => {
    const { router } = await mountAt(`/content?tab=access&userId=${USER_A}`)

    await router.push('/content')
    await flushPromises()

    expect(getMenuTree).toHaveBeenCalledTimes(1)
  })

  // 다른 화면으로 떠날 때도 route는 컴포넌트가 사라지기 전에 먼저 바뀐다.
  it('다른 경로로 이동하면 조회하지 않는다', async () => {
    const { router } = await mountAt(`/content?tab=access&userId=${USER_A}`)

    await router.push('/directory')
    await flushPromises()

    expect(getAccessRules).toHaveBeenCalledTimes(1)
    expect(getMenuTree).not.toHaveBeenCalled()
  })
})

describe('ContentAccessView 탭별 조회 상태', () => {
  function tab(wrapper: VueWrapper, label: string) {
    const button = wrapper.findAll('[role="tab"]').find((item) => item.text() === label)
    if (!button) throw new Error(`탭을 찾지 못했습니다: ${label}`)
    return button
  }

  // "아직 조회하지 않았다"를 빈 배열로 판단하면 권한 규칙이 0건인 사용자는 탭을 누를 때마다 같은 요청을 되풀이한다.
  it('0건으로 조회를 마친 탭은 다시 눌러도 재조회하지 않는다', async () => {
    const { wrapper } = await mountAt(`/content?userId=${USER_A}`)
    expect(wrapper.text()).toContain('조회된 접근 정책이 없습니다.')

    await tab(wrapper, '메뉴 트리').trigger('click')
    await flushPromises()
    expect(wrapper.text()).toContain('조회된 메뉴가 없습니다.')

    await tab(wrapper, '접근 권한').trigger('click')
    await tab(wrapper, '메뉴 트리').trigger('click')
    await tab(wrapper, '접근 권한').trigger('click')
    await flushPromises()

    expect(getAccessRules).toHaveBeenCalledTimes(1)
    expect(getMenuTree).toHaveBeenCalledTimes(1)
    wrapper.unmount()
  })

  // query 조건이 바뀌면 이전 조건의 접근 정책 결과는 무효다 — 조회 완료 플래그가 그 결과를 붙들고 있으면 안 된다.
  it('query 조건이 비면 조회를 마친 접근 권한 탭도 다시 읽는다', async () => {
    vi.mocked(getAccessRules).mockResolvedValue([{ id: 1, menuCode: 'M1', userId: USER_A, accessYn: 'Y' }])
    const { router, wrapper } = await mountAt(`/content?tab=access&userId=${USER_A}`)
    expect(getAccessRules).toHaveBeenCalledTimes(1)

    await router.push('/content')
    await flushPromises()
    expect(getMenuTree).toHaveBeenCalledTimes(1)

    await tab(wrapper, '접근 권한').trigger('click')
    await flushPromises()

    expect(getAccessRules).toHaveBeenCalledTimes(2)
    expect(getAccessRules).toHaveBeenLastCalledWith(expect.objectContaining({ userId: undefined }))
    wrapper.unmount()
  })
})
import { onMounted, watch } from 'vue'
import { useRoute, type LocationQuery } from 'vue-router'

// 같은 key가 두 번 오면 vue-router는 배열을 준다. 화면은 첫 값만 조건으로 쓴다.
export function readQueryValue(query: LocationQuery, key: string): string {
  const value = query[key]
  if (Array.isArray(value)) return value[0] || ''
  return value || ''
}

// 사용자·부서 화면의 딥링크는 경로는 그대로 두고 query만 바꾸므로 vue-router가 화면을 다시 mount하지 않는다.
// query를 mount 시점에만 읽으면 이전 사용자의 조건과 결과가 그대로 남아, 다른 사용자의 자료를 보고 있다고 오해하게 된다.
// 그래서 mount 시점과 query가 바뀔 때 같은 적용 함수를 부른다.
export function useRouteQuerySync(keys: string[], apply: () => void): void {
  const route = useRoute()
  // 다른 화면으로 떠날 때도 route는 컴포넌트가 사라지기 전에 먼저 바뀐다. 진입 시점의 경로를 기억해 구분한다.
  const viewPath = route.path

  watch(
    // query 값에 들어갈 수 없는 문자로 이어 붙여야 서로 다른 조건 조합이 같은 값으로 보이지 않는다.
    () => keys.map((key) => readQueryValue(route.query, key)).join('\u0000'),
    (next, previous) => {
      if (next === previous || route.path !== viewPath) return
      apply()
    },
  )

  onMounted(apply)
}
